    // The instanceof check uses is_subclass_of() which walks the superclass chain.
    if (method == "getContext" &&
        (class_name.find("View") != std::string::npos ||
         class_name.find("Context") != std::string::npos)) {
        // First, try the shadow path — ViewShadow stores context_object_id
        // when the View constructor captures the Context arg.
        if (shadow_registry_ != nullptr) {
            framework::CallContext ctx;
            if (!args.empty() && args[0].type == DalvikType::OBJECT_REF) {
                ctx.has_receiver = true;
                ctx.receiver_id = args[0].object_id;
                ctx.receiver_class = args[0].class_desc;
                ctx.class_name = args[0].class_desc;
            }
            ctx.method = "getContext";
            auto cr = shadow_registry_->dispatch(ctx);
            if (cr.handled) {
                result = call_result_to_dalvik(cr);
                status = ApiCallTrace::Status::IMPLEMENTED;
                return true;
            }
        }
        // Fallback: return the LaunchActivity singleton
        result = get_or_create_singleton("Lorg/telegram/ui/LaunchActivity;");
        status = ApiCallTrace::Status::IMPLEMENTED;
        return true;
    }

    // P0.7 — Context.getApplicationContext → Context singleton
    // ────────────────────────────────────────────────────────────────────────
    // [R341-APPCTX] AOSP identity law: getApplicationContext() returns THE
    // Application instance ActivityThread created (handleBindApplication).
    // Hilt/DI chains type-check this object: dooz23 Lk2;.b pc=776..880 did
    // getApplicationContext() → instanceof Application → ContextWrapper
    // base walk → threw ISE "Could not find an Application in the given
    // context" when the previous law served a plain Context singleton.
    if (method == "getApplicationContext" &&
        (class_name.find("Context") != std::string::npos ||
         class_name.find("Activity") != std::string::npos ||
         class_name.find("Application") != std::string::npos ||
         class_name.find("Application;") != std::string::npos)) {
        if (application_object_id_ != 0 &&
            heap_.has_object(application_object_id_)) {
            result = DalvikValue::make_object(
                application_object_id_,
                application_class_desc_.empty()
                    ? "Landroid/app/Application;"
                    : application_class_desc_);
        } else {
            result = get_or_create_singleton("Landroid/content/Context;");
        }
        status = ApiCallTrace::Status::IMPLEMENTED;
        return true;
    }

    // ────────────────────────────────────────────────────────────────────────
    // P0.2 — Context/Activity/View.getResources → Resources singleton
    // F-141d (S72-W3): View receivers added — AOSP View.java law:
    // getResources() returns mResources (captured from the view's
    // context/ViewRootImpl at construction), NEVER null for a constructed
    // view. Evidence (dooz): the Compose init lambda (we.run) runs the
    // class-identity idiom  view.getResources().getClass(); the STUBBED
    // null answer fired the F-141 null-receiver NPE law (we.run pc=42)
    // and unwound the composition chain out of MainActivity.onCreate.
    // One Resources singleton = the engine's single resource authority
    // (same object Activity.getResources() answers; the per-configuration
    // Resources overlay subset is not modeled).
    // S85-FIX (F-NEW-163): the original guard was a class-NAME substring
    // match (Context/Activity/View). App subclasses of the Context family
    // (e.g. net.sourceforge.solitaire_cg.Solitaire extends Application;
    // custom Application/Service subclasses) matched NONE of the
    // substrings, so getResources() answered null →
    // Resources.getDisplayMetrics NPE at SolitaireView.<init> (S85 fan-out:
    // net.sourceforge.solitaire_cg, com.aurora.store, dev.lexip.hecate,
    // com.nononsenseapps.notepad …). AOSP law: EVERY Context-family
